            if (data.lastUpdatedMedia && data.lastUpdatedMedia > localMediaTimestampRef.current) {
              needsSync = true;
            }
            if (data.lastUpdatedChannels && data.lastUpdatedChannels > localChannelsTimestampRef.current) {
