                   >
                     {showPassInput ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                   </button>
                 </div>
               </div>
 
               <div>
                 <label className="block text-zinc-400 font-bold mb-1.5">New Admin Password *</label>
                 <input
                   type={showPassInput ? 'text' : 'password'}
