                     <Key className="w-4 h-4" />
                   )}
                   <span>Save New Admin Password</span>
                 </button>
               </div>
             </form>
           </div>
         </div>
       )}
 
       {/* ---------------- CREATE SUBSCRIPTION PLAN MODAL ---------------- */}
