  if (totalSec <= 0) return;
  const media = movies.find((m) => m.id === mediaId);
  if (!media) return;

  const percentage = Math.min(100, Math.round((currentSec / totalSec) * 100));

  setContinueWatching((prev) => {
    const filtered = prev.filter((item) => item.mediaId !== mediaId);
