 const safeStorage = {
   get: (key: string, fallback: string | null = null): string | null => {
     try {
       if (typeof window !== 'undefined' && window.localStorage) {
         return window.localStorage.getItem(key) ?? fallback;
       }
       return fallback;
     } catch {
       return fallback;
     }
   },
   set: (key: string, value: string): void => {
     try {
       if (typeof window !== 'undefined' && window.localStorage) {
