         if (deferredPrompt) {
           try {
             deferredPrompt.prompt();
             deferredPrompt.userChoice.then(({ outcome }: { outcome: string }) => {
               if (outcome === 'accepted') {
                 setIsInstallable(false);
                 setShowInstallBanner(false);
               }
               setDeferredPrompt(null);
             }).catch(() => {
               setShowInstallGuideModal(true);
             });
