import React from 'react';
import { useAuth, SUPER_ADMIN_EMAIL } from '../../context/AuthContext';
import { useApp } from '../../context/AppContext';
import { Movie } from '../../types';
import { addMovieToFirestore, updateMovieInFirestore, deleteMovieFromFirestore } from '../../lib/firebase';
import { AdminDashboard } from '../AdminDashboard';
import { ShieldAlert, Lock } from 'lucide-react';

interface AdminViewProps {
  movies?: Movie[];
  onUpdateMovies?: (movies: Movie[]) => void;
}

export const AdminView: React.FC<AdminViewProps> = () => {
  const { user, isAdmin } = useAuth();
  const { adminToken, ownerToken, movies, addMedia, updateMedia, deleteMedia } = useApp();

  // 1. Verify credentials & master admin email
  const isAuthorized =
    isAdmin ||
    (user?.email || '').toLowerCase() === SUPER_ADMIN_EMAIL.toLowerCase() ||
    Boolean(adminToken) ||
    Boolean(ownerToken);

  // 2. Lock screen if non-admin attempts to access
  if (!isAuthorized) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6">
        <div className="bg-[#111111] border border-red-900/30 rounded-3xl p-8 max-w-md w-full text-center text-white shadow-2xl animate-fade-in">
          <div className="w-16 h-16 mx-auto mb-4 rounded-2xl bg-red-500/10 border border-red-500/30 flex items-center justify-center text-red-400">
            <ShieldAlert className="w-8 h-8" />
          </div>
          <h2 className="text-2xl font-black text-red-500 mb-2">Access Denied</h2>
          <p className="text-sm text-zinc-400 leading-relaxed">
            Only the Universal Admin (<span className="text-white font-medium">{SUPER_ADMIN_EMAIL}</span>) can manage movie content and system settings.
          </p>
        </div>
      </div>
    );
  }

  // 3. Admin functions update Cloud Firestore and sync to all users
  const handleAddMovie = async (newMovieData: Movie) => {
    await addMovieToFirestore(newMovieData);
    await addMedia(newMovieData);
  };

  const handleUpdateMovie = async (id: string, updates: Partial<Movie>) => {
    await updateMovieInFirestore(id, updates);
    const existing = movies.find((m) => m.id === id);
    if (existing) {
      await updateMedia({ ...existing, ...updates });
    }
  };

  const handleDeleteMovie = async (id: string) => {
    await deleteMovieFromFirestore(id);
    await deleteMedia(id);
  };

  return <AdminDashboard />;
};

export default AdminView;

