   const [ownerToken, setOwnerToken] = useState<string | null>(() => {
     const saved = safeStorage.get(STORAGE_KEYS.OWNER_TOKEN, null);
     if (saved && saved.startsWith('owner_tok_local_')) {
       safeStorage.set(STORAGE_KEYS.OWNER_TOKEN, '');
       return null;
