           isLive: true,
           currentProgram: `${namePart} Live Broadcast`,
           currentProgramRw: `Gukurikira ${namePart} Ako Kanya`,
           isPremiumOnly: false
         };
       } else if (line.startsWith('http://') || line.startsWith('https://')) {
         if (currentInfo && currentInfo.name) {
           parsedChannels.push({
             ...(currentInfo as LiveChannel),
             streamUrl: line
           });
           currentInfo = null;
