const startDownload = async (media: MediaItem, episode?: Episode): Promise<boolean> => {
  if (!isPromotionFreeActive && currentUser.subscription.plan !== 'premium') {
    setShowSubscriptionModal(true);
    return false;
  }

  const downloadId = `dl_${Date.now()}`;
  const newDownload: DownloadedItem = {
    id: downloadId,
    mediaId: media.id,
    title: episode ? `${media.title} - S${episode.season} E${episode.episodeNumber}` : media.title,
    poster: episode ? episode.thumbnail : media.poster,
    type: media.type,
    season: episode?.season,
    episodeNumber: episode?.episodeNumber,
    fileSize: episode ? '680 MB' : '1.8 GB',
    quality: media.quality,
    downloadedAt: new Date().toISOString(),
    videoUrl: episode ? episode.videoUrl : media.videoUrl
  };

  setDownloads((prev) => [newDownload, ...prev.filter((d) => d.id !== downloadId)]);
  return true;
};

const deleteDownload = (downloadId: string) => {
