     try {
       eventSource = new EventSource('/api/sync/events');
       eventSource.onmessage = (event) => {
         try {
           const data = JSON.parse(event.data);
           if (data && data.type === 'sync') {
             forceCloudSync();
           }
         } catch {
           // ignore non-json messages
         }
       };
       eventSource.onerror = () => {
