       console.warn('[Firestore subscribeMovies listener notice]:', fsErr);
     }
 
     return () => {
       if (unsubscribeFirestoreMovies) {
         unsubscribeFirestoreMovies();
       }
       if (eventSource) {
         eventSource.close();
       }
       if (broadcastChan) {
         broadcastChan.close();
       }
       clearInterval(interval);
