display.text:
// Downloads are FREE for ALL users — movies, episodes, seasons & parts.
// The real video FILE is saved to the user's local device storage.
const startDownload = async (media: MediaItem, episode?: Episode, part?: MediaPart): Promise<boolean> => {
  const sourceUrl = episode ? episode.videoUrl : part ? part.videoUrl : media.videoUrl;
  const label = episode
    ? `${media.title} - S${episode.season}E${episode.episodeNumber}`
    : part
    ? `${media.title} - ${part.title || `Part ${part.partNumber}`}`
    : media.title;
    .replace(/[^a-z0-9\-_ ]/gi, '')
    .trim()
    .replace(/\s+/g, '_');
  const extension = sourceUrl && /\.mp4|\.webm|\.ogg|\.mkv|\.mov|\.m4v/i.test(sourceUrl)
    ? (sourceUrl.match(/\.mp4|\.webm|\.ogg|\.mkv|\.mov|\.m4v/i)?.[0] ?? '.mp4')
    : '.mp4';
  const fileName = `${safeTitle || 'netstudio_video'}${extension}`;

  /**
   * Saves the actual video FILE to the user's local device storage
   * (browser Downloads folder), then records it in the in-app library.
   */
  const saveFileToLocalDevice = async () => {
    if (!sourceUrl) return;
    try {
      // Preferred path: fetch as Blob -> forces a true local file copy
      const res = await fetch(sourceUrl, { mode: 'cors' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const objectUrl = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = objectUrl;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000);
    } catch {
      // Fallback (CORS-restricted hosts): let the browser handle the URL natively
      const a = document.createElement('a');
      a.href = sourceUrl;
      a.download = fileName;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      document.body.appendChild(a);
      a.click();
      a.remove();
    }
  };

  await saveFileToLocalDevice();

  const newDownload: DownloadedItem = {
    id: `dl_${Date.now()}`,
    mediaId: media.id,
    title: episode ? `${media.title} - S${episode.season} E${episode.episodeNumber}` : media.title,
    poster: episode?.thumbnail || media.poster,
    type: media.type,
    season: episode?.season,
    episodeNumber: episode?.episodeNumber,
    fileSize: 'Saved to device',
    quality: media.quality || 'HD',
    downloadedAt: new Date().toISOString(),
    videoUrl: sourceUrl
  };

